import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const Graph = () => {
    const [data, setData] = useState([]);
    const [lastPrice, setLastPrice] = useState(null);
    const maxDataPoints = 10; // Número máximo de puntos en la gráfica

    const fetchDollarToMXN = async () => {
        try {
            const response = await axios.get(`https://api.exchangerate-api.com/v4/latest/USD`);
            const price = response.data.rates.MXN;

            if (lastPrice !== price) {
                const newDataPoint = { name: `T-${data.length}`, price };
                setData((prevData) => {
                    const updatedData = [...prevData, newDataPoint];
                    // Limitar la longitud de los datos
                    return updatedData.length > maxDataPoints ? updatedData.slice(updatedData.length - maxDataPoints) : updatedData;
                });
                setLastPrice(price);
            }
        } catch (error) {
            console.error('Error fetching dollar price:', error);
        }
    };

    useEffect(() => {
        fetchDollarToMXN();
        const interval = setInterval(fetchDollarToMXN, 10000);
        return () => clearInterval(interval);
    }, []);

    return (
        <ResponsiveContainer width="100%" height={200}>
            <LineChart data={data}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" interval={1} /> {/* Reduce la frecuencia de los ticks */}
                <YAxis tickFormatter={(value) => `$${value.toFixed(2)}`} />
                <Tooltip formatter={(value) => [`$${value.toFixed(2)}`, 'Precio del Dólar']} />
                <Legend />
                <Line type="monotone" dataKey="price" stroke="#8884d8" />
            </LineChart>
        </ResponsiveContainer>
    );
};

export default Graph;
